#!/bin/bash
# Insert notification permission request inside MainScreen
sed -i '/val vpnPermissionLauncher = rememberLauncherForActivityResult(/i \    val notificationPermissionLauncher = rememberLauncherForActivityResult(\n        contract = ActivityResultContracts.RequestPermission()\n    ) { _ -> }\n\n    LaunchedEffect(Unit) {\n        if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.TIRAMISU) {\n            if (androidx.core.content.ContextCompat.checkSelfPermission(context, android.Manifest.permission.POST_NOTIFICATIONS) != android.content.pm.PackageManager.PERMISSION_GRANTED) {\n                notificationPermissionLauncher.launch(android.Manifest.permission.POST_NOTIFICATIONS)\n            }\n        }\n    }\n' app/src/main/java/com/example/ui/screens/MainScreen.kt
